/* Patient experience preview. Fictional records only; no clinical data or messages
   are fetched, transmitted, or persisted. Reloading resets this demo session. */
(() => {
  'use strict';
  const $ = s => document.querySelector(s);
  const escape = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paths = {
    home:'<path d="m3 10 9-7 9 7v10H5V10"/><path d="M9 20v-7h6v7"/>',
    plan:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 10h6M9 14h6M9 18h3"/>',
    calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4M17 3v4M3 11h18M8 15h2M14 15h2"/>',
    results:'<path d="M9 3h6M10 3v6L4 19a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L14 9V3M7 15h10"/>',
    pill:'<path d="m8 4-4 4a6 6 0 0 0 8 8l4-4a6 6 0 0 0-8-8Z"/><path d="m7 7 8 8"/>',
    message:'<path d="M21 11a8 8 0 0 1-8 8H8l-5 3v-8a8 8 0 0 1 8-11h2a8 8 0 0 1 8 8Z"/><path d="M8 9h8M8 13h5"/>',
    folder:'<path d="M3 7V5h7l2 3h9v12H3Z"/><path d="M3 8h9"/>',
    help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4M12 17h.01"/>',
    bell:'<path d="M5 16h14l-2-4V8a5 5 0 0 0-10 0v4ZM10 20h4"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',
    video:'<rect x="3" y="6" width="12" height="12" rx="2"/><path d="m15 10 6-3v10l-6-3"/>',
    heart:'<path d="M20 5c-3-3-7 0-8 2-1-2-5-5-8-2-6 6 8 15 8 15S26 11 20 5Z"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
    shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Z"/><path d="m8 11 3 3 5-6"/>',
    settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor"/><circle cx="15" cy="17" r="3" fill="currentColor"/>',
    document:'<path d="M5 3h9l5 5v13H5ZM14 3v6h5M8 13h8M8 17h6"/>',
    people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-5a6 6 0 0 1 12 0v5M17 4a3 3 0 0 1 0 6M19 14a5 5 0 0 1 2 7"/>',
    search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
    leaf:'<path d="M20 3C4 1 1 14 8 18c7 5 13-4 12-15ZM6 21 17 7"/>'
  };
  const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.document}</svg>`;
  const today = new Date();
  const date = (offset,hour=9,minute=0) => {const d=new Date(today.getFullYear(),today.getMonth(),today.getDate()+offset,hour,minute);return d;};
  const fmt = (d,options={month:'short',day:'numeric'}) => new Date(d).toLocaleDateString([],options);
  const time = d => new Date(d).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});
  const stamp = d => `${fmt(d,{weekday:'long',month:'long',day:'numeric'})} at ${time(d)}`;
  const badge = (text,tone='') => `<span class="badge ${tone}">${escape(text)}</span>`;
  const button = (text,action,id='',type='secondary',symbol='') => `<button class="${type}" data-action="${action}" data-id="${escape(id)}">${symbol?icon(symbol):''}${escape(text)}</button>`;
  const linkView = (text,view) => `<button class="subtle" data-view="${view}">${escape(text)}</button>`;
  const state = {view:'home',tab:'upcoming',resultFilter:'all',taskDone:new Set(),taken:new Set(),acknowledged:new Set(),readResults:new Set(),readThreads:new Set(),drafts:[],requests:[],logs:[],questions:'',checklist:new Set(),preferences:{email:true,sms:false,medications:true,visits:true,results:true,largeText:false,contrast:false},thread:'team'};
  let mediaStream=null,deviceRequest=0,toastTimer;
  const mobileNavigation=matchMedia('(max-width:760px)');
  function syncNavigation(){const open=$('.sidebar').classList.contains('open');$('.sidebar').inert=mobileNavigation.matches&&!open;$('#menuToggle').setAttribute('aria-expanded',String(open));$('#menuToggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');}
  mobileNavigation.addEventListener('change',syncNavigation);
  const appointments = [
    {id:'primary',title:'Primary care follow-up',clinician:'Dr. Riley Bennett',specialty:'Family medicine',date:date(3,10,30),kind:'In-person visit',location:'Northstar Family Health',address:'100 Example Avenue, Suite 200',status:'Confirmed',reason:'Review your care plan, medications, and recent lab results.',prep:['Bring your medication list and any questions.','Bring your insurance card and photo ID.','Complete your visit checklist before arrival.'],duration:30},
    {id:'video',title:'Care plan check-in',clinician:'Nurse Avery Williams',specialty:'Care coordination',date:date(7,14),kind:'Video visit',location:'Your private online waiting room',address:'Join from a quiet, private place.',status:'Scheduled',reason:'Talk through your follow-up questions and next steps.',prep:['Have your medication list nearby.','Choose a private space and check your device.','Write down anything you want to discuss.'],duration:20},
    {id:'labs',title:'Follow-up laboratory visit',clinician:'Northstar Laboratory',specialty:'Lab services',date:date(12,8,15),kind:'Lab visit',location:'Northstar Laboratory',address:'100 Example Avenue, Ground Floor',status:'Scheduled',reason:'Complete the tests ordered by your care team.',prep:['Check the instructions on your test order.','Ask the lab whether any preparation is needed.'],duration:20}
  ];
  const pastVisits=[{title:'Annual wellness visit',date:date(-8),clinician:'Dr. Riley Bennett',summary:'Reviewed your health history, medication list, and preventive care. Follow-up labs ordered.'},{title:'Care coordination call',date:date(-22),clinician:'Nurse Avery Williams',summary:'Reviewed access to care, preferred pharmacy, and upcoming visit preparation.'}];
  const results=[
    {id:'lipids',title:'Lipid panel',type:'lab',date:date(-2),status:'Reviewed by your doctor',tone:'',summary:'Your doctor has reviewed this report and left a note for your next visit.',note:'We will review these results together at your follow-up. Bring your current medication list and any questions you have.',values:[['Total cholesterol','196','mg/dL','< 200'],['HDL cholesterol','52','mg/dL','≥ 40'],['LDL cholesterol','118','mg/dL','< 100'],['Triglycerides','130','mg/dL','< 150']],trend:[132,125,118],trendLabel:'LDL cholesterol (mg/dL)',flagged:'LDL cholesterol'},
    {id:'cbc',title:'Complete blood count',type:'lab',date:date(-2),status:'New result',tone:'blue',summary:'A new report is available. Reference intervals come from the fictional reporting laboratory.',note:'If you have questions about any value, ask your care team to explain it in the context of your health history.',values:[['Hemoglobin','13.8','g/dL','12.0–16.0'],['White blood cells','6.4','×10³/µL','4.0–11.0'],['Platelets','245','×10³/µL','150–450']],trend:[13.5,13.7,13.8],trendLabel:'Hemoglobin (g/dL)'},
    {id:'metabolic',title:'Basic metabolic panel',type:'lab',date:date(-8),status:'Reviewed by your doctor',tone:'',summary:'View the original measurements, units, and laboratory reference intervals.',note:'Reviewed during your wellness follow-up planning.',values:[['Sodium','140','mmol/L','135–145'],['Potassium','4.2','mmol/L','3.5–5.0'],['Creatinine','0.9','mg/dL','0.6–1.2']],trend:[.9,1,.9],trendLabel:'Creatinine (mg/dL)'},
    {id:'imaging',title:'Chest X-ray report',type:'imaging',date:date(-35),status:'Reviewed by your doctor',tone:'',summary:'Fictional radiology report and clinician follow-up.',note:'The sample report has been reviewed. Contact your care team if you have questions about the terminology.',report:'Sample radiology report: No acute cardiopulmonary abnormality described. This is fictional demonstration content, not an interpretation of a real scan.'}
  ];
  const medications=[
    {id:'lisinopril',name:'Lisinopril',strength:'10 mg tablet',purpose:'Blood pressure',schedule:'Morning',instructions:'Fictional prescription: one tablet by mouth daily. Follow your own pharmacy label and clinician’s instructions for real medication use.',prescriber:'Dr. Riley Bennett',refills:'2 refills remaining',supply:'30-day supply',pickup:true},
    {id:'atorvastatin',name:'Atorvastatin',strength:'20 mg tablet',purpose:'Cholesterol',schedule:'Evening',instructions:'Fictional prescription: one tablet by mouth daily, as directed by the prescriber.',prescriber:'Dr. Riley Bennett',refills:'1 refill remaining',supply:'30-day supply',pickup:false}
  ];
  const tasks=[
    {id:'pickup',title:'Pick up your prescription',detail:'Lisinopril · ready at Northstar Pharmacy',category:'Medication',action:'pharmacy',due:'Today'},
    {id:'visit-prep',title:'Get ready for your next visit',detail:'A short checklist for your follow-up',category:'Appointment',action:'checklist',due:fmt(appointments[0].date)},
    {id:'results',title:'Review your new lab report',detail:'Complete blood count · available '+fmt(date(-2)),category:'Results',action:'result',target:'cbc',due:'New'},
    {id:'referral',title:'Follow up on your physical therapy referral',detail:'Referral received · scheduling is the next step',category:'Referral',action:'referral',due:'This week'}
  ];
  const threads={
    team:{name:'Your primary care team',initials:'RB',role:'Dr. Riley Bennett & team',subject:'Your follow-up plan',date:date(-2,15,20),message:'Hi Alex, your recent lab reports are available in Results. We can review them together at your follow-up. Please bring your medication list and any questions. You can prepare those questions here before the visit.'},
    nurse:{name:'Care coordination',initials:'AW',role:'Nurse Avery Williams',subject:'Getting ready for your video visit',date:date(-1,10),message:'Your video check-in is scheduled. You can use the device check in Visits to test your camera and microphone. Please choose a quiet, private place and have your medication list nearby.'},
    pharmacy:{name:'Medication support',initials:'NS',role:'Northstar care team',subject:'Prescription pickup reminder',date:date(-1,11),message:'The sample prescription shown in Medications is ready for pickup at Northstar Pharmacy. Check the pharmacy details before heading out. If you have an access or cost concern, draft a message to your care team.'}
  };
  const sections=[['home','home','Overview'],['plan','plan','My care plan'],['visits','calendar','Visits'],['results','results','Results'],['medications','pill','Medications'],['messages','message','Messages'],['records','folder','Health records']];
  function renderNav(){
    $('#patientNav').innerHTML=sections.map(([id,symbol,name])=>`<button class="nav-item ${state.view===id?'active':''}" data-view="${id}" ${state.view===id?'aria-current="page"':''}>${icon(symbol)}<span>${name}</span>${id==='results'&&!state.readResults.has('cbc')?'<span class="nav-count">1</span>':''}${id==='messages'&&state.readThreads.size<3?`<span class="nav-count">${3-state.readThreads.size}</span>`:''}</button>`).join('');
    $('#helpNav').innerHTML=icon('help')+'<span>Help & support</span>';
    $('#helpNav').classList.toggle('active',state.view==='support');
    $('#notificationButton').innerHTML=icon('bell');
    $('#breadcrumb').textContent=`Your care / ${sections.find(s=>s[0]===state.view)?.[2]||({support:'Help & support',settings:'Preferences'}[state.view])}`;
  }
  const header=(eyebrow,title,description,extra='')=>`<div class="page-header"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;
  const info=text=>`<div class="info-strip">${icon('info')}<span>${text}</span></div>`;
  function nextVisitCard(){const a=appointments[0];return `<section class="card next-visit"><span class="eyebrow">YOUR NEXT APPOINTMENT</span><h2>${a.title}</h2><p>A little preparation. A more helpful conversation.</p><div class="visit-person"><span class="avatar">RB</span><div><strong>${a.clinician}</strong><small>${a.specialty} · Northstar Family Health</small></div></div><div class="appointment-meta"><span>${icon('calendar')}${fmt(a.date,{weekday:'short',month:'short',day:'numeric'})}</span><span>${icon('clock')}${time(a.date)}</span><span>${icon('pin')}In person</span></div><div class="button-row">${button('Prepare for your visit','checklist','','primary')}${button('View appointment','appointment',a.id)}</div></section>`;}
  function taskRows(items=tasks){return items.map(t=>`<div class="task-row ${state.taskDone.has(t.id)?'done':''}"><input class="task-check" type="checkbox" data-task="${t.id}" id="task-${t.id}" ${state.taskDone.has(t.id)?'checked':''} aria-label="Mark ${escape(t.title)} complete in this demo"><div class="task-copy"><label for="task-${t.id}"><strong>${t.title}</strong></label><small>${t.detail}</small></div>${button(t.due,t.action,t.target||t.id,'subtle')}</div>`).join('');}
  function doctorNote(){return `<section class="card doctor-note"><div class="card-heading"><h2>A note from your doctor</h2>${icon('plan')}</div><div class="note-author"><span class="avatar small">RB</span><div><strong>Dr. Riley Bennett</strong><small>Following your wellness visit · ${fmt(date(-8))}</small></div></div><blockquote>“Let’s take this one step at a time. Keep a home blood pressure log if you’re already monitoring, bring your medication list, and write down any questions before our follow-up. We’ll review your results together.”</blockquote><div class="note-footer"><small>${state.acknowledged.has('doctor-note')?'Marked as read in this demo':'Part of your care plan'}</small>${button(state.acknowledged.has('doctor-note')?'Read':'Mark as read','acknowledge-note','','subtle')}</div></section>`;}
  function pickupCard(){return `<section class="card pickup-card"><div class="card-heading"><h2>Ready for pickup</h2>${badge('At your pharmacy','warm')}</div><div class="pickup-top"><span class="square-icon">${icon('pill')}</span><div><h3>Lisinopril</h3><span class="muted small-text">10 mg tablet · 30-day supply</span></div></div><div class="pharmacy-address"><strong>Northstar Pharmacy</strong>120 Example Avenue<br>Sample hours: Mon–Fri, 9 AM–6 PM</div><p>Check your prescription label and pharmacy details before pickup.</p>${button('View pickup details','pharmacy','','subtle')}</section>`;}
  function resultRows(){return results.slice(0,2).map(r=>`<div class="result-preview"><span class="square-icon">${icon('results')}</span><div class="task-copy"><strong>${r.title}</strong><small>${fmt(r.date)} · ${r.id==='cbc'&&!state.readResults.has(r.id)?'New result':'Reviewed'}</small></div>${button('View','result',r.id,'subtle')}</div>`).join('');}
  function renderHome(){return header('A LITTLE CLARITY, EVERY DAY','Your care. All together.','Welcome back, Alex. Here’s what’s next for you.',`<span class="today-label">${fmt(today,{weekday:'long',month:'long',day:'numeric'})}</span>`)+`<div class="home-grid"><div class="stack">${nextVisitCard()}<section class="card"><div class="card-heading"><h2>Your next steps</h2><span class="muted small-text">${tasks.filter(t=>!state.taskDone.has(t.id)).length} to do</span></div>${taskRows(tasks.slice(0,3))}<div style="margin-top:17px">${linkView('See your full care plan','plan')}</div></section></div><div class="stack">${doctorNote()}<section class="card"><div class="card-heading"><h2>Your latest results</h2>${linkView('See all','results')}</div>${resultRows()}</section>${pickupCard()}</div></div><div class="quick-actions"><button class="quick-action" data-action="compose">${icon('message')}Message your care team</button><button class="quick-action" data-action="refill" data-id="lisinopril">${icon('pill')}Request a refill</button><button class="quick-action" data-action="waiting">${icon('video')}Prepare for a video visit</button><button class="quick-action" data-view="records">${icon('folder')}View health records</button></div>`;}
  function renderPlan(){return header('ONE STEP AT A TIME','Your plan, made personal.','The instructions, people, and follow-ups that keep your care moving.')+`<div class="two-column"><div class="stack"><section class="card"><div class="card-heading"><h2>Your next steps</h2>${badge(`${tasks.filter(t=>state.taskDone.has(t.id)).length} of ${tasks.length} complete`)}</div>${taskRows()}<p class="section-note">Checklist changes are for this demo session only.</p></section>${doctorNote()}<section class="card"><div class="card-heading"><h2>Referral tracker</h2>${badge('Scheduling needed','warm')}</div><h3>Physical therapy consultation</h3><p class="muted small-text">Ordered by Dr. Riley Bennett · ${fmt(date(-8))}</p><div class="care-timeline"><div class="timeline-item"><time>${fmt(date(-8))}</time><h3>Referral placed</h3><p>Northstar Rehabilitation · initial assessment.</p></div><div class="timeline-item"><time>${fmt(date(-5))}</time><h3>Referral received</h3><p>The receiving clinic has the sample referral. An appointment has not been booked.</p></div><div class="timeline-item"><h3>Next step: arrange your visit</h3><p>Check insurance coverage and scheduling details with the care coordinator.</p>${button('Ask about this referral','referral','','secondary')}</div></div></section></div><div class="stack"><section class="card"><div class="card-heading"><h2>Your care team</h2>${icon('people')}</div>${Object.entries(threads).slice(0,2).map(([id,t])=>`<div class="care-team-row"><span class="avatar">${t.initials}</span><div><h3>${t.role}</h3><p>${id==='team'?'Primary care':'Care coordination'}</p>${button('Draft a message','compose',id,'subtle')}</div></div>`).join('')}<p class="section-note">Contact details are fictional in this preview.</p></section><section class="card"><div class="card-heading"><h2>Health journal</h2>${icon('heart')}</div><p class="muted small-text">Keep track of questions, symptoms, or readings you want to discuss. Entries are not monitored or shared.</p>${button('Add a demo entry','journal','','secondary')}${state.logs.slice(-3).reverse().map(l=>`<div class="details-panel"><h3>${escape(l.type)} · ${fmt(l.date)}</h3><p>${escape(l.text)}</p></div>`).join('')}</section><section class="card"><h2>Small steps count</h2><p class="muted small-text">Your example goal: prepare for the follow-up visit.</p><div class="goal-progress"><span style="width:${state.checklist.size/4*100}%"></span></div><p class="small-text muted">${state.checklist.size} of 4 preparation steps complete</p>${button('Open your checklist','checklist','','subtle')}</section><section class="card"><h2>Preventive care</h2><p class="muted small-text">Discuss vaccines, screening, and preventive care at your next visit. Recommendations depend on your personal history.</p>${button('Add a question for your doctor','questions','','subtle')}</section></div></div>`;}
  function renderVisits(){const a=appointments;return header('ROOM FOR EVERY QUESTION','A clearer view of your visits.','Appointments, preparation, and follow-up in one place.',button('Request an appointment','request-visit','','primary','calendar'))+`<div class="tabs" role="tablist" aria-label="Visit history"><button class="tab" data-tab="upcoming" role="tab" aria-selected="${state.tab!=='past'}">Upcoming visits</button><button class="tab" data-tab="past" role="tab" aria-selected="${state.tab==='past'}">Past visits</button></div><div class="two-column"><div class="stack">${state.tab==='past'?pastVisits.map((v,i)=>`<section class="card"><div class="card-heading"><h2>${v.title}</h2>${badge('Completed','neutral')}</div><p class="muted small-text">${fmt(v.date,{dateStyle:'long'})} · ${v.clinician}</p><p>${v.summary}</p><div class="button-row">${button('Visit summary','document',`visit-${i}`)}${button('Ask a follow-up question','compose','team','subtle')}</div></section>`).join(''):`<section class="card list-card">${a.map(v=>`<div class="list-item"><div class="date-tile"><span>${fmt(v.date,{month:'short'})}</span><strong>${v.date.getDate()}</strong></div><div class="list-item-main"><h3>${v.title}</h3><p>${v.clinician}<br>${fmt(v.date,{weekday:'long'})} at ${time(v.date)} · ${v.kind}<br>${v.location}</p>${badge(v.status,v.kind==='Video visit'?'blue':'')}<div class="button-row">${button(v.kind==='Video visit'?'Open waiting room':'Visit details',v.kind==='Video visit'?'waiting':'appointment',v.id,v.kind==='Video visit'?'primary':'secondary',v.kind==='Video visit'?'video':'')}${button('Add to calendar','calendar',v.id,'subtle')}</div></div></div>`).join('')}</section>`}</div><div class="stack"><section class="card"><h2>Before you go</h2><p class="muted small-text">A few details now can make your visit easier.</p>${button('Complete your checklist','checklist','','secondary')}<div class="details-panel"><h3>Your questions, ready</h3><p>${state.questions?escape(state.questions):'Save the questions you don’t want to forget.'}</p>${button('Edit questions','questions','','subtle')}</div></section><section class="card"><h2>Plans change.</h2><p class="muted small-text">Need another time, an interpreter, transportation assistance, or an accessibility accommodation? Prepare a request for your team.</p>${button('Request a change','reschedule',a[0].id,'subtle')}</section><section class="card"><h2>Video visit essentials</h2><p class="muted small-text">Test your camera and microphone, check your connection, and find a private place before your appointment.</p>${button('Open device check','waiting','','secondary')}</section></div></div>`;}
  function renderResults(){const visible=results.filter(r=>state.resultFilter==='all'||r.type===state.resultFilter);return header('THE FULL PICTURE','Your results, within reach.','Original reports, reference intervals, and your care team’s notes.')+info('Laboratory flags are not diagnoses. Your care team interprets results alongside your history. All reports here are fictional.')+`<div class="tabs" role="tablist" aria-label="Result category">${[['all','All results'],['lab','Laboratory'],['imaging','Imaging']].map(([id,label])=>`<button class="tab" role="tab" aria-selected="${state.resultFilter===id}" data-result-filter="${id}">${label}</button>`).join('')}</div><div class="two-column"><section class="card list-card">${visible.map(r=>`<div class="list-item"><span class="square-icon">${icon(r.type==='lab'?'results':'document')}</span><div class="list-item-main"><h3>${r.title}</h3><p>Collected ${fmt(r.date,{dateStyle:'long'})}<br>${r.summary}</p>${badge(r.id==='cbc'&&state.readResults.has('cbc')?'Viewed':r.status,r.tone)}<div class="button-row">${button('Open report','result',r.id)}${button('Download sample','download-result',r.id,'subtle','download')}</div></div></div>`).join('')}</section><div class="stack"><section class="card"><h2>Questions are welcome.</h2><p class="muted small-text">Not sure what a result means for you? Include the report name in a question to your clinician.</p>${button('Draft a result question','compose','results','secondary')}</section><section class="card"><h2>Waiting on a result?</h2><p class="muted small-text">The example portal includes results available to this practice. Outside providers may hold additional reports.</p>${button('Ask about a missing result','compose','missing-result','subtle')}</section></div></div>`;}
  function renderMedications(){return header('THE DETAILS THAT MATTER','Your medications, organized.','Know what’s on your list, what’s ready, and what to ask your team.',button('Medication questions','compose','medications','secondary'))+info('These are fictional prescriptions. Demo dose checkoffs are personal notes, not verified adherence records or medication instructions.')+`<div class="two-column"><div class="stack">${medications.map(m=>`<section class="card med-card"><div class="med-top"><div><span class="eyebrow">${m.purpose}</span><h3>${m.name} <span class="muted">${m.strength}</span></h3></div>${badge(m.pickup?'Ready for pickup':'Active',m.pickup?'warm':'')}</div><p>${m.instructions}</p><div class="med-schedule"><div><strong>${m.schedule}</strong><br><span>Per the fictional prescription</span></div><div><strong>${m.supply}</strong><br><span>${m.refills}</span></div></div><label class="med-check"><input type="checkbox" data-med="${m.id}" ${state.taken.has(m.id)?'checked':''}>Mark today’s dose as taken in this demo</label><div class="button-row">${button('Medication details','medication',m.id)}${button('Refill request','refill',m.id,'subtle')}${m.pickup?button('Pickup details','pharmacy','','subtle'):''}</div></section>`).join('')}<section class="card"><h2>Keep your list complete.</h2><p class="muted small-text">Tell your care team about medicines from other prescribers, over-the-counter products, supplements, side effects, or anything you’ve stopped taking.</p>${button('Draft a medication update','compose','medication-update','secondary')}</section></div><div class="stack">${pickupCard()}<section class="card"><h2>Allergies on file</h2><h3>Penicillin</h3><p class="muted small-text">Reported reaction: rash.<br>Recorded in this fictional profile.</p>${button('Request a correction','compose','allergy','subtle')}</section><section class="card"><h2>Having trouble getting medication?</h2><p class="muted small-text">Cost, transportation, refill timing, and pharmacy availability can affect your care. Let your team know what’s getting in the way.</p>${button('Ask for medication support','compose','medication-access','subtle')}</section></div></div>`;}
  function renderMessages(){const t=threads[state.thread];return header('A CONVERSATION, CONTINUED','Stay close to your care team.','Review example conversations and prepare questions between visits.',button('New message draft','compose','','primary','message'))+info('Preview conversations only. Messages are not sent or monitored. This is not an urgent-care or emergency channel.')+`<section class="card" style="padding:0"><div class="message-layout"><div class="message-list" role="group" aria-label="Conversations">${Object.entries(threads).map(([id,item])=>`<button class="thread-button ${state.thread===id?'active':''}" data-thread="${id}" aria-pressed="${state.thread===id}"><strong>${item.name}</strong><small>${item.subject}</small><p>${item.message}</p></button>`).join('')}<button class="thread-button ${state.thread==='drafts'?'active':''}" data-thread="drafts" aria-pressed="${state.thread==='drafts'}"><strong>Your local drafts (${state.drafts.length})</strong><small>Not sent to the care team</small></button></div><div class="message-thread">${state.thread==='drafts'?`<h2>Your drafts</h2><p class="muted small-text">These exist only until this page is reloaded.</p>${state.drafts.length?state.drafts.map((d,i)=>`<div class="details-panel"><h3>${escape(d.subject)}</h3><p>${escape(d.message)}</p><span class="badge neutral">Draft · not sent</span>${button('Edit draft','edit-draft',String(i),'subtle')}${button('Delete draft','delete-draft',String(i),'subtle')}</div>`).join(''):'<div class="empty-state"><h3>A place for your questions.</h3><p>Save a draft when something comes to mind.</p></div>'}`:`<div class="care-team-row"><span class="avatar">${t.initials}</span><div><h3>${t.role}</h3><p>${t.subject}</p></div></div><span class="thread-date">${stamp(t.date)} · Fictional message</span><div class="thread-bubble">${t.message}</div>${button('Draft a reply','compose',state.thread,'secondary')}`}</div></div></section>`;}
  function renderRecords(){return header('YOUR HEALTH STORY','The details, in one place.','Visit summaries, allergies, reports, and the records you may need.',button('Download sample care summary','download-summary','','secondary','download'))+`<div class="two-column"><div class="stack"><section class="card"><div class="card-heading"><h2>Documents & visit summaries</h2>${icon('folder')}</div>${[['visit-0','Annual wellness visit summary',fmt(date(-8))],['care-plan','Your care plan','Instructions & follow-up'],['med-list','Medication & allergy list','Example active list'],['referral','Physical therapy referral','Referral details']].map(([id,title,sub])=>`<div class="document-item"><span class="square-icon">${icon('document')}</span><div><strong>${title}</strong><small>${sub}</small></div>${button('Open','document',id,'subtle')}</div>`).join('')}</section><section class="card"><h2>Health history</h2><div class="care-timeline"><div class="timeline-item"><time>${fmt(date(-2))}</time><h3>Lab reports received</h3><p>Lipid panel and complete blood count.</p>${linkView('View results','results')}</div><div class="timeline-item"><time>${fmt(date(-8))}</time><h3>Annual wellness visit</h3><p>Dr. Riley Bennett · care plan and follow-up orders.</p>${button('Read summary','document','visit-0','subtle')}</div><div class="timeline-item"><time>${fmt(date(-22))}</time><h3>Care coordination</h3><p>Reviewed appointment preparation and pharmacy preferences.</p></div></div></section></div><div class="stack"><section class="card"><h2>Your profile</h2><dl class="small-text"><dt class="muted">Name</dt><dd>Alex Morgan · fictional patient</dd><dt class="muted">Date of birth</dt><dd>April 12, 1988</dd><dt class="muted">Preferred language</dt><dd>English</dd></dl>${button('Review preferences','preferences','','subtle')}</section><section class="card"><h2>Allergies & health concerns</h2><div class="details-panel"><h3>Penicillin</h3><p>Reported rash · example allergy record.</p></div><p class="muted small-text">Example care focus: blood pressure and cholesterol follow-up.</p>${button('Request a record correction','compose','record-correction','subtle')}</section><section class="card"><h2>Immunization records</h2><p class="muted small-text">No verified immunization feed is connected in this preview. A missing record does not mean a vaccination is due.</p>${button('Ask for immunization records','compose','immunizations','subtle')}</section><section class="card"><h2>Outside records</h2><p class="muted small-text">Need records from another clinician, a hospital stay, or a specialist? Prepare a records request.</p>${button('Draft a records request','records-request','','secondary')}</section></div></div>`;}
  function renderSupport(){return header('CARE INCLUDES THE PRACTICAL THINGS','Let’s make care easier.','Find the right place for a question, a barrier, or a next step.')+`<div class="three-column"><section class="card"><span class="square-icon">${icon('people')}</span><h2 style="margin-top:20px">Care coordination</h2><p class="muted small-text">Referrals, transportation, language services, accessibility, or help preparing for a visit.</p>${button('Prepare a support request','support-request','','secondary')}</section><section class="card"><span class="square-icon">${icon('document')}</span><h2 style="margin-top:20px">Bills & coverage</h2><p class="muted small-text">Understand where a bill came from, ask about costs, or request insurance and financial assistance information.</p>${button('View billing help','billing','','secondary')}</section><section class="card"><span class="square-icon">${icon('shield')}</span><h2 style="margin-top:20px">Caregiver access</h2><p class="muted small-text">Plan how a trusted person could help with care while keeping control of what they can access.</p>${button('Explore caregiver access','caregiver','','secondary')}</section></div><div class="two-column" style="margin-top:22px"><section class="card"><h2>Who to contact</h2><ul class="support-list"><li>Medical questions<small>Draft a question to your primary care team in Messages.</small></li><li>Appointment changes<small>Visit details include rescheduling and accommodation request drafts.</small></li><li>Pharmacy questions<small>Review pickup information and prepare a medication support request.</small></li><li>Urgent concerns<small>This preview cannot contact a clinician or call for help. Use your established urgent-care or local emergency channels.</small></li></ul></section><section class="card"><h2>Useful before your next visit</h2><p class="muted small-text">Prepare the questions, medication list, and details you want to bring into the room.</p><div class="button-row">${button('Visit preparation','checklist')}${button('Care summary','download-summary','','secondary','download')}</div><div class="details-panel"><h3>Your privacy matters</h3><p>No real health record, insurer, pharmacy, or telehealth provider is connected. All records in this experience are fictional.</p></div></section></div>`;}
  function renderSettings(){return header('A SPACE THAT WORKS FOR YOU','Your preferences. Your choice.','Explore notification, access, and accessibility settings for the patient experience.')+info('Preference changes apply only to this preview session. No reminders are scheduled and no access permissions are granted.')+`<div class="two-column"><div class="stack"><section class="card"><h2>Reminder preferences</h2>${[['email','Email reminders','Example delivery channel'],['sms','Text message reminders','A live system would require a verified phone number and explicit consent'],['visits','Appointment reminders','Before visits and when appointment details change'],['medications','Medication & pickup reminders','Refill and pharmacy pickup updates'],['results','New result notifications','When a new report becomes available']].map(([id,label,sub])=>`<div class="settings-row"><label for="pref-${id}">${label}<small>${sub}</small></label><input type="checkbox" id="pref-${id}" data-pref="${id}" ${state.preferences[id]?'checked':''}></div>`).join('')}</section><section class="card"><h2>Accessibility</h2>${[['largeText','Larger text','Increase text size throughout this preview'],['contrast','Stronger contrast','Use darker secondary text and borders']].map(([id,label,sub])=>`<div class="settings-row"><label for="pref-${id}">${label}<small>${sub}</small></label><input type="checkbox" id="pref-${id}" data-pref="${id}" ${state.preferences[id]?'checked':''}></div>`).join('')}<p class="section-note">The portal also follows your device’s reduced-motion preference.</p></section></div><div class="stack"><section class="card"><h2>Profile & communication</h2><p class="muted small-text">Alex Morgan · fictional patient<br>Language: English<br>Timezone: ${escape(Intl.DateTimeFormat().resolvedOptions().timeZone)}</p>${button('Edit example contact preferences','preferences','','secondary')}</section><section class="card"><h2>Trusted helpers</h2><p class="muted small-text">No one has access through this preview. A live caregiver connection would need identity verification and granular, revocable consent.</p>${button('Review caregiver options','caregiver','','subtle')}</section><section class="card"><h2>Manage demo data</h2><p class="muted small-text">Drafts, checkoffs, and journal entries are held in memory. Reloading resets them. No data is sent to a care team.</p>${button('Reset this preview','reset','','secondary')}</section></div></div>`;}
  function render(){renderNav();$('#content').innerHTML=({home:renderHome,plan:renderPlan,visits:renderVisits,results:renderResults,medications:renderMedications,messages:renderMessages,records:renderRecords,support:renderSupport,settings:renderSettings}[state.view]||renderHome)();document.title=`${sections.find(s=>s[0]===state.view)?.[2]||'Your care'} · moBILLity`;}
  function navigate(view){if(![...sections.map(s=>s[0]),'support','settings'].includes(view))view='home';state.view=view;if(view==='messages'&&state.thread!=='drafts')state.readThreads.add(state.thread);history.replaceState(null,'',`#${view}`);render();$('#content').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});$('.sidebar').classList.remove('open');syncNavigation();}
  function toast(text){const t=$('#portalToast');t.textContent=text;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,4200);}
  function stopMedia(){deviceRequest++;mediaStream?.getTracks().forEach(t=>t.stop());mediaStream=null;const testButton=document.querySelector('[data-action="test-devices"]');if(testButton)testButton.disabled=false;}
  function showDialog(title,html,eyebrow='YOUR CARE'){stopMedia();$('#dialogTitle').textContent=title;$('#dialogContent').innerHTML=html;$('#dialogEyebrow').textContent=eyebrow;if(!$('#portalDialog').open)$('#portalDialog').showModal();}
  function closeDialog(){stopMedia();$('#portalDialog').close();}
  function download(name,text,type='text/plain'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  const demoNotice='<p class="section-note">Fictional demonstration content. No request is sent; changes reset on reload.</p>';
  function appointmentDialog(id){const a=appointments.find(v=>v.id===id)||appointments[0];showDialog(a.title,`${badge(a.status)}<dl><dt>When</dt><dd>${stamp(a.date)} (${a.duration} minutes)</dd><dt>With</dt><dd>${a.clinician}</dd><dt>Visit type</dt><dd>${a.kind}</dd><dt>Where</dt><dd>${a.location}<br>${a.address}</dd></dl><p>${a.reason}</p><div class="details-panel"><h3>Before your visit</h3>${a.prep.map(p=>`<p>${p}</p>`).join('')}</div><div class="dialog-footer">${button('Add to calendar','calendar',a.id,'secondary','calendar')}${button('Request a change','reschedule',a.id)}${button('Preparation checklist','checklist','','subtle')}</div>`,'APPOINTMENT');}
  function trendChart(result){
    const values=result.trend,low=Math.min(...values),high=Math.max(...values);
    const span=high-low||1;
    const points=values.map((n,i)=>({x:50+i*160,y:72-(n-low)/span*38,n}));
    return `<svg class="lab-chart" viewBox="0 0 420 120" role="img" aria-label="Three fictional historical values: ${values.join(', ')}"><path d="M30 85H390" stroke="#d6e4da"/><polyline points="${points.map(p=>`${p.x},${p.y}`).join(' ')}" fill="none" stroke="#639b7b" stroke-width="2"/>${points.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="5" fill="#087f75"/><text x="${p.x}" y="${p.y-12}" text-anchor="middle">${p.n}</text><text x="${p.x}" y="105" text-anchor="middle">${fmt(date([-180,-90,-2][i]))}</text>`).join('')}</svg>`;
  }
  function labDialog(id){const r=results.find(r=>r.id===id);if(!r)return;state.readResults.add(id);render();showDialog(r.title,`${badge(r.status,r.tone)}<p class="section-note">Fictional sample · collected ${fmt(r.date,{dateStyle:'long'})} · Northstar Laboratory</p>${r.values?`<div class="table-overflow"><table class="result-table"><thead><tr><th>Test</th><th>Result</th><th>Lab reference</th></tr></thead><tbody>${r.values.map(([test,value,unit,range])=>`<tr><td>${test}</td><td><strong>${value}</strong><small>${unit}</small></td><td>${range}${r.flagged===test?'<small>Outside sample lab interval</small>':''}</td></tr>`).join('')}</tbody></table></div><div class="details-panel"><h3>${r.trendLabel} · sample history</h3>${trendChart(r)}</div>`:`<div class="details-panel"><h3>Radiology report</h3><p>${r.report}</p></div>`}<div class="details-panel"><h3>From your care team</h3><p>${r.note}</p></div><p class="section-note">Reference intervals are laboratory-specific and are not a diagnosis. Sample chart is illustrative.</p><div class="dialog-footer">${button('Ask about this result','compose',`result-${r.id}`,'primary')}${button('Download sample report','download-result',r.id,'secondary','download')}</div>`,'RESULT DETAILS');}
  function checklistDialog(){const items=['Review medications and allergies','Prepare insurance card and photo ID','Write down your questions','Check location or video setup'];showDialog('A little preparation helps.',`<p>Your follow-up with Dr. Riley Bennett is ${fmt(appointments[0].date,{weekday:'long',month:'long',day:'numeric'})}.</p><ul class="checklist">${items.map((item,i)=>`<li><input type="checkbox" id="prep-${i}" data-prep="${i}" ${state.checklist.has(String(i))?'checked':''}><label for="prep-${i}">${item}</label></li>`).join('')}</ul><div class="dialog-footer">${button('Add questions','questions','','primary')}${button('View appointment','appointment','primary')}</div>${demoNotice}`,'BEFORE YOUR VISIT');}
  function composeDialog(id='',editIndex=null){const old=editIndex!==null?state.drafts[editIndex]:null;const subjects={results:'Question about a result','missing-result':'Missing test result',medications:'Medication question','medication-update':'Medication list update',allergy:'Allergy record correction','medication-access':'Help getting my medication',immunizations:'Immunization record request','record-correction':'Health record correction'};const result=id.startsWith('result-')?results.find(r=>r.id===id.slice(7)):null;const subject=old?.subject||subjects[id]||(result?`Question about ${result.title}`:'');showDialog(editIndex!==null?'Edit your message draft':'What’s on your mind?',`<p>Prepare a non-urgent question for your care team. This preview cannot send or monitor messages.</p><form id="composeForm" data-index="${editIndex??''}"><div class="field"><label for="messageRecipient">To</label><select id="messageRecipient">${['Primary care team','Care coordination','Medication support','Billing support'].map(name=>`<option ${name===(old?.recipient||(id==='nurse'?'Care coordination':id==='pharmacy'?'Medication support':'Primary care team'))?'selected':''}>${name}</option>`).join('')}</select></div><div class="field"><label for="messageSubject">Subject</label><input id="messageSubject" value="${escape(subject)}" required maxlength="140"></div><div class="field"><label for="messageBody">Your message</label><textarea id="messageBody" required maxlength="3000" placeholder="Use fictional information only in this preview.">${escape(old?.message||'')}</textarea></div><div class="dialog-footer"><button class="primary" type="submit">Save local draft</button><button class="secondary" type="button" disabled>Send unavailable in preview</button></div></form>${demoNotice}`,'MESSAGES');}
  function requestDialog(kind,id=''){const titles={refill:'Request a prescription refill',reschedule:'Request an appointment change','request-visit':'Request a new appointment','records-request':'Request outside records',referral:'Ask about your referral','support-request':'Ask for practical support',billing:'Ask a billing question',caregiver:'Plan caregiver access'};const m=medications.find(m=>m.id===id);showDialog(titles[kind]||'Prepare a request',`${info(kind==='caregiver'?'This does not invite anyone or grant access. A live portal must verify identities and obtain specific, revocable consent.':'This is a request draft. No appointment, prescription, coverage decision, or care plan changes until the appropriate team reviews a real request.')}<form id="requestForm" data-kind="${kind}"><div class="field"><label for="requestTopic">${kind==='refill'?'Medication':'Topic'}</label><input id="requestTopic" value="${escape(m?`${m.name} ${m.strength}`:titles[kind]||'Care request')}" required maxlength="160"></div>${kind==='reschedule'||kind==='request-visit'?'<div class="field"><label for="preferredDate">Preferred date</label><input type="date" id="preferredDate"></div>':''}${kind==='caregiver'?'<div class="field"><label for="caregiverScope">Access to discuss</label><select id="caregiverScope"><option>Appointments only</option><option>Appointments and reminders</option><option>Records and care coordination</option></select><small>A live invitation would require verified recipient details.</small></div>':''}<div class="field"><label for="requestDetails">Details for the team</label><textarea id="requestDetails" required maxlength="2000" placeholder="Use fictional details. Include the question or help you need."></textarea></div><div class="dialog-footer"><button class="primary" type="submit">Save request draft</button></div></form>${demoNotice}`,'CARE REQUEST');}
  function waitingDialog(){showDialog('Your video visit starts here.',`${badge('Demo waiting room','blue')}<p>${stamp(appointments[1].date)} · ${appointments[1].clinician}</p><div class="video-stage" id="videoStage"><div><span class="avatar">AM</span><p>Your camera is off</p></div></div><div id="deviceStatus" class="section-note" role="status">No clinician is connected. Camera and microphone access is optional and begins only when you choose to test.</div><div class="dialog-footer">${button('Test camera & microphone','test-devices','','secondary','video')}${button('Stop device test','stop-devices','','secondary')}${button('I need help joining','compose','video-help','subtle')}</div><div class="details-panel"><h3>Before you join a real visit</h3><p>Find a private place, check your connection, and have your medication list ready. A live telehealth provider and verified appointment access are required to connect with a clinician.</p></div>`,'TELEHEALTH');}
  function pharmacyDialog(){showDialog('Your prescription pickup.',`${badge('Sample status: ready for pickup','warm')}<h3 style="margin-top:20px">Lisinopril · 10 mg tablet</h3><p>30-day supply · prescribed by Dr. Riley Bennett</p><div class="details-panel"><h3>Northstar Pharmacy</h3><p>120 Example Avenue<br>Sample hours: Monday–Friday, 9 AM–6 PM<br>Contact number is not connected in this preview.</p></div><p>Bring the information required by your pharmacy. Review the medication name and label with the pharmacist when you collect it.</p><div class="dialog-footer">${button('Mark pickup task complete','complete-pickup','','primary')}${button('Ask for pickup support','compose','medication-access')}</div>${demoNotice}`,'MEDICATION PICKUP');}
  function documentText(id){if(id==='med-list')return `Medication & allergy list\n\n${medications.map(m=>`${m.name} ${m.strength}\n${m.instructions}`).join('\n\n')}\n\nAllergy: penicillin; reported rash.`;if(id==='referral')return 'Physical therapy referral\nOrdered by Dr. Riley Bennett.\nStatus: received by Northstar Rehabilitation; appointment not scheduled.\nAsk care coordination about scheduling and coverage.';return `Visit summary — ${fmt(date(-8),{dateStyle:'long'})}\nAlex Morgan (fictional patient)\nDr. Riley Bennett\n\nCare focus: blood pressure and cholesterol follow-up.\nPlan: review medication list and lab reports at follow-up. Keep a home log if already monitoring and bring questions.\nFollow-up: ${stamp(appointments[0].date)}\n\nAll information is fictional.`;}
  function documentDialog(id){showDialog(id==='med-list'?'Medication & allergy list':id==='referral'?'Referral details':'Your visit & care summary',`<div class="details-panel" style="white-space:pre-wrap">${escape(documentText(id))}</div><div class="dialog-footer">${button('Download sample text','download-document',id,'secondary','download')}${button('Ask about this document','compose','document-question','subtle')}</div>`,'HEALTH RECORDS');}
  function journalDialog(){showDialog('Make a note for yourself.',`<p>This journal is a personal demo workspace. Entries are not reviewed, shared, or used to adjust your care.</p><form id="journalForm"><div class="field"><label for="journalType">Entry type</label><select id="journalType"><option>Question for my clinician</option><option>Home reading</option><option>Symptom note</option><option>Medication question</option><option>General wellbeing</option></select></div><div class="field"><label for="journalText">Your note</label><textarea id="journalText" required maxlength="1000" placeholder="Fictional sample note only."></textarea></div><button class="primary" type="submit">Add demo entry</button></form>${demoNotice}`,'HEALTH JOURNAL');}
  function questionsDialog(){showDialog('Bring the questions that matter.',`<form id="questionsForm"><div class="field"><label for="visitQuestions">Questions for your next visit</label><textarea id="visitQuestions" maxlength="2000" placeholder="What do these results mean? What should I watch for?">${escape(state.questions)}</textarea></div><button class="primary" type="submit">Save questions in this demo</button></form>${demoNotice}`,'VISIT PREPARATION');}
  function preferencesDialog(){showDialog('How would you like to be reached?',`<form id="contactForm"><div class="field"><label for="preferredLanguage">Preferred language</label><select id="preferredLanguage"><option>English</option><option>Spanish</option><option>Another language — request an interpreter</option></select></div><div class="field"><label for="accessNeeds">Communication or accessibility needs</label><textarea id="accessNeeds" maxlength="1000" placeholder="Example: I would like an interpreter for my next visit."></textarea></div><button class="primary" type="submit">Save preference request draft</button></form>${demoNotice}`,'YOUR PREFERENCES');}
  async function testDevices(){
    if(mediaStream)return;
    const status=$('#deviceStatus'),testButton=document.querySelector('[data-action="test-devices"]');
    if(!navigator.mediaDevices?.getUserMedia){status.textContent='Device testing is unavailable in this browser. Try a supported browser on a secure connection.';return;}
    const request=++deviceRequest;
    testButton.disabled=true;
    status.textContent='Waiting for your device permission…';
    try{
      const stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});
      if(request!==deviceRequest||!$('#portalDialog').open||!$('#videoStage')){stream.getTracks().forEach(t=>t.stop());return;}
      mediaStream=stream;
      $('#videoStage').innerHTML='<video autoplay playsinline muted aria-label="Your local camera preview"></video>';
      $('#videoStage video').srcObject=stream;
      status.textContent='Camera and microphone access granted. The local preview is not recorded or transmitted; no clinician is connected.';
    }catch(error){
      if(request===deviceRequest&&$('#deviceStatus'))$('#deviceStatus').textContent=error.name==='NotAllowedError'?'Permission was not granted. You can continue exploring with your devices off.':'Your device could not be opened. Check that it is connected and not in use by another app.';
    }finally{if(request===deviceRequest&&testButton.isConnected)testButton.disabled=false;}
  }
  function calendarDownload(id){const a=appointments.find(v=>v.id===id)||appointments[0];const utc=d=>new Date(d).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');download(`sample-${a.id}-visit.ics`,`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//moBILLity//Fictional preview//EN\r\nBEGIN:VEVENT\r\nUID:sample-${a.id}-${a.date.getTime()}@preview.mobillity\r\nDTSTAMP:${utc(new Date())}\r\nDTSTART:${utc(a.date)}\r\nDTEND:${utc(new Date(a.date.getTime()+a.duration*60000))}\r\nSUMMARY:DEMO ONLY - ${a.title}\r\nLOCATION:${a.location}\r\nDESCRIPTION:Fictional sample appointment. This is not a real booking.\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`,'text/calendar');toast('Downloaded a clearly labeled sample calendar event.');}
  function dispatch(action,id){
    if(action==='appointment')appointmentDialog(id);
    else if(action==='checklist')checklistDialog();
    else if(action==='result')labDialog(id);
    else if(action==='pharmacy')pharmacyDialog();
    else if(action==='waiting')waitingDialog();
    else if(action==='test-devices')testDevices();
    else if(action==='stop-devices'){stopMedia();$('#videoStage').innerHTML='<div><span class="avatar">AM</span><p>Your camera is off</p></div>';$('#deviceStatus').textContent='Device access stopped. No clinician is connected.';}
    else if(action==='compose')composeDialog(id);
    else if(action==='billing')showDialog('A clearer path through costs.',`<p>No billing or insurance system is connected. A balance, coverage decision, or payment due cannot be verified here.</p><div class="details-panel"><h3>Before an appointment</h3><p>Ask about an estimate, in-network status, referral requirements, or prior authorization. Your insurer and provider must confirm actual coverage.</p></div><div class="details-panel"><h3>After a visit</h3><p>Request an itemized statement or explanation of benefits. If something looks unfamiliar, ask the billing team to review it.</p></div><div class="details-panel"><h3>If cost is a barrier</h3><p>Ask about financial assistance, payment-plan availability, or medication-access support. No eligibility decision or payment is made in this preview.</p></div><div class="dialog-footer">${button('Draft a billing question','billing-draft','','primary')}${button('Ask about medication costs','compose','medication-access')}</div>`,'BILLING & COVERAGE');
    else if(action==='billing-draft')requestDialog('billing');
    else if(['refill','reschedule','request-visit','records-request','referral','support-request','caregiver'].includes(action))requestDialog(action,id);
    else if(action==='acknowledge-note'){state.acknowledged.add('doctor-note');render();toast('Note marked as read in this demo.');}
    else if(action==='journal')journalDialog();
    else if(action==='questions')questionsDialog();
    else if(action==='preferences')preferencesDialog();
    else if(action==='document')documentDialog(id);
    else if(action==='medication'){const m=medications.find(m=>m.id===id);if(m)showDialog(`${m.name} ${m.strength}`,`<dl><dt>For</dt><dd>${m.purpose}</dd><dt>Prescriber</dt><dd>${m.prescriber}</dd><dt>Schedule</dt><dd>${m.schedule}</dd><dt>Supply</dt><dd>${m.supply}</dd><dt>Refills</dt><dd>${m.refills}</dd></dl><p>${m.instructions}</p><p>This is an example prescription, not medication advice. Use the pharmacy label and prescriber instructions for your own medications.</p><div class="dialog-footer">${button('Draft a refill request','refill',m.id,'primary')}${button('Ask a question','compose','medications')}</div>`,'MEDICATION DETAILS');}
    else if(action==='complete-pickup'){state.taskDone.add('pickup');closeDialog();render();toast('Pickup task marked complete for this demo. Pharmacy status is unchanged.');}
    else if(action==='calendar')calendarDownload(id);
    else if(action==='download-result'){const r=results.find(r=>r.id===id);if(r)download(`fictional-${r.id}-report.txt`,`FICTIONAL SAMPLE — NOT A REAL MEDICAL RECORD\n\n${r.title}\nCollected ${fmt(r.date,{dateStyle:'long'})}\n\n${r.values?r.values.map(v=>v.join(' | ')).join('\n'):r.report}\n\nCare team note: ${r.note}`);}
    else if(action==='download-document')download(`fictional-${id}-summary.txt`,'FICTIONAL SAMPLE — NOT A REAL MEDICAL RECORD\n\n'+documentText(id));
    else if(action==='download-summary')download('fictional-care-summary.txt',`FICTIONAL SAMPLE — NOT A REAL MEDICAL RECORD\n\n${documentText('care-plan')}\n\n${documentText('med-list')}`);
    else if(action==='edit-draft')composeDialog('',Number(id));
    else if(action==='delete-draft'){state.drafts.splice(Number(id),1);render();toast('Local draft deleted.');}
    else if(action==='notifications')showDialog('Your care reminders.',`<div class="stack">${tasks.map(t=>`<div class="details-panel"><h3>${t.title}</h3><p>${t.detail}</p>${button('Open',t.action,t.target||t.id,'subtle')}</div>`).join('')}</div><p class="section-note">Example reminders only. No notifications are scheduled.</p>`,'REMINDERS');
    else if(action==='reset')showDialog('Reset this demo session?',`<p>This clears local drafts, notes, checklist progress, and preferences. No real clinical record will be changed.</p><div class="dialog-footer">${button('Reset preview','confirm-reset','','primary')}</div>`,'DEMO SETTINGS');
    else if(action==='confirm-reset')location.reload();
  }
  document.addEventListener('click',event=>{
    const view=event.target.closest('[data-view]');if(view){closeDialog();navigate(view.dataset.view);return;}
    const action=event.target.closest('[data-action]');if(action){dispatch(action.dataset.action,action.dataset.id||'');return;}
    const tab=event.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;render();return;}
    const filter=event.target.closest('[data-result-filter]');if(filter){state.resultFilter=filter.dataset.resultFilter;render();return;}
    const thread=event.target.closest('[data-thread]');if(thread){state.thread=thread.dataset.thread;if(state.thread!=='drafts')state.readThreads.add(state.thread);render();}
  });
  document.addEventListener('change',event=>{
    const t=event.target;
    if(t.dataset.task){t.checked?state.taskDone.add(t.dataset.task):state.taskDone.delete(t.dataset.task);render();}
    if(t.dataset.med){t.checked?state.taken.add(t.dataset.med):state.taken.delete(t.dataset.med);toast('Demo dose checkoff updated. It is not shared with your care team.');}
    if(t.dataset.prep!==undefined){t.checked?state.checklist.add(t.dataset.prep):state.checklist.delete(t.dataset.prep);if(state.checklist.size===4)state.taskDone.add('visit-prep');else state.taskDone.delete('visit-prep');render();}
    if(t.dataset.pref){state.preferences[t.dataset.pref]=t.checked;document.body.classList.toggle('large-text',state.preferences.largeText);document.body.classList.toggle('high-contrast',state.preferences.contrast);toast('Preview preference updated. No live delivery settings changed.');}
  });
  document.addEventListener('submit',event=>{
    const form=event.target;if(!['composeForm','requestForm','journalForm','questionsForm','contactForm'].includes(form.id))return;
    event.preventDefault();
    if(form.id==='composeForm'){
      const subject=$('#messageSubject').value.trim(),message=$('#messageBody').value.trim();if(!subject||!message)return;
      const draft={subject,message,recipient:$('#messageRecipient').value,date:new Date()};if(form.dataset.index!=='')state.drafts[Number(form.dataset.index)]=draft;else state.drafts.push(draft);
      closeDialog();state.thread='drafts';navigate('messages');toast('Draft saved for this session. Nothing was sent.');
    } else if(form.id==='requestForm'){
      const subject=$('#requestTopic').value.trim(),detail=$('#requestDetails').value.trim();if(!subject||!detail)return;
      const extra=$('#preferredDate')?.value?`\nPreferred date: ${$('#preferredDate').value}`:$('#caregiverScope')?`\nAccess to discuss: ${$('#caregiverScope').value}`:'';
      state.drafts.push({subject,message:detail+extra,recipient:'Care coordination',date:new Date()});closeDialog();state.thread='drafts';navigate('messages');toast('Request draft saved. It has not been submitted.');
    } else if(form.id==='journalForm'){
      const text=$('#journalText').value.trim();if(!text)return;state.logs.push({type:$('#journalType').value,text,date:new Date()});closeDialog();navigate('plan');toast('Demo journal entry added. It is not monitored or shared.');
    } else if(form.id==='questionsForm'){state.questions=$('#visitQuestions').value.trim();closeDialog();render();toast('Questions saved for this demo session.');}
    else if(form.id==='contactForm'){state.drafts.push({subject:'Communication preference request',message:`Language: ${$('#preferredLanguage').value}\n${$('#accessNeeds').value.trim()}`,recipient:'Care coordination',date:new Date()});closeDialog();state.thread='drafts';navigate('messages');toast('Preference request saved as a local draft.');}
  });
  $('#closeDialog').addEventListener('click',closeDialog);
  $('#portalDialog').addEventListener('close',stopMedia);
  $('#portalDialog').addEventListener('cancel',stopMedia);
  $('#menuToggle').addEventListener('click',()=>{$('.sidebar').classList.toggle('open');syncNavigation();});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('.sidebar').classList.contains('open')){$('.sidebar').classList.remove('open');syncNavigation();$('#menuToggle').focus();}});
  window.addEventListener('pagehide',stopMedia);
  window.addEventListener('hashchange',()=>{const view=location.hash.slice(1)||'home';if([...sections.map(s=>s[0]),'support','settings'].includes(view)){state.view=view;render();}});
  state.view=location.hash.slice(1)||'home';if(![...sections.map(s=>s[0]),'support','settings'].includes(state.view))state.view='home';syncNavigation();render();
})();
